  globals.window["GAMEBOY_CONTAINER"] = null
  globals.window["GAMEBOY_WRAPPER"] = null
  globals.window["GAMEBOY_CTX"] = null
  globals.window["GAMEBOY_JOYSTICK"] = null
  globals.window["GAMEBOY_LAST_MOUSE_X"] = null
  globals.window["GAMEBOY_LAST_MOUSE_Y"] = null
  globals.window["GAMEBOY_BACK_TEXT"] = "BACK"
  globals.window["GAMEBOY_SOUND_TEXT"] = "SOUND"
  globals.window["GAMEBOY_LOAD_TEXT"] = "LOAD"
  globals.window["GAMEBOY_SAVE_TEXT"] = "SAVE"

  // Constants
  globals.window["GAMEBOY_WIDTH"] = 160
  globals.window["GAMEBOY_HEIGHT"] = 144
  globals.window["GAMEBOY_TARGET_FPS"] = 4194304.0 / 70224.0 // ~59.7275
  globals.window["GAMEBOY_FRAME_TIME"] =
    1000.0 / globals.window["GAMEBOY_TARGET_FPS"]

  // Libretro joypad button IDs
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_UP"] = 4
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_DOWN"] = 5
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_LEFT"] = 6
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_RIGHT"] = 7
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_SELECT"] = 2
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_START"] = 3
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_A"] = 8
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_B"] = 0
  globals.window["GAMEBOY_RETRO_DEVICE_ID_JOYPAD_MASK"] = 256

  // Libretro environment commands
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_ROTATION"] = 1
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_GET_CAN_DUPE"] = 3
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_MESSAGE"] = 6
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_PIXEL_FORMAT"] = 10
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_INPUT_DESCRIPTORS"] = 11
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_VARIABLES"] = 16
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_GET_VARIABLE"] = 15
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_GET_VARIABLE_UPDATE"] = 17
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_SUPPORT_NO_GAME"] = 18
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_GET_LOG_INTERFACE"] = 27
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_SET_SUPPORT_ACHIEVEMENTS"] = 42
  globals.window["GAMEBOY_RETRO_ENVIRONMENT_GET_MESSAGE_INTERFACE_VERSION"] = 59

  globals.window["GAMEBOY_RUNNING"] = false
  globals.window["GAMEBOY_PAUSED"] = false
  globals.window["GAMEBOY_MUTED"] = false
  globals.window["GAMEBOY_LAST_FRAME_TIME"] = 0
  globals.window["GAMEBOY_RAF_ID"] = null
  globals.window["GAMEBOY_IMAGE_DATA"] = null
  globals.window["GAMEBOY_IMAGE_PIXELS"] = null
  globals.window["GAMEBOY_STATE_INPUT"] = null

